import React, { useRef } from 'react';
import {
  Alert,
  Box,
  LinearProgress,
  Typography,
} from '@mui/material';
import CloudUploadOutlinedIcon from '@mui/icons-material/CloudUploadOutlined';
import DownloadOutlinedIcon from '@mui/icons-material/DownloadOutlined';
import { Button } from '../../../../components/ui';
import { useFeatureTheme } from '../../../../theme/hooks/useFeatureTheme';

export default function LeadSendTemplateSheetTab({
  copy,
  styles,
  sheetFile,
  sheetValidation,
  isUploading,
  uploadProgress,
  prefilledDownloadLabel,
  embedded = false,
  onDownloadPrefilled,
  onDownloadBlank,
  onDownloadErrorSheet,
  onFileSelect,
}) {
  const fileInputRef = useRef(null);
  const { semantic, typography } = useFeatureTheme();

  const invalidCount = sheetValidation?.invalidRows?.length ?? 0;
  const hasRowErrors = invalidCount > 0;
  const fileErrors = sheetValidation?.fileErrors ?? [];
  const columnErrors = sheetValidation?.columnErrors ?? [];

  const handleZoneClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (event) => {
    const file = event.target.files?.[0];
    onFileSelect?.(file ?? null);
    event.target.value = '';
  };

  return (
    <Box sx={embedded ? styles?.leadSendTemplateBulkSheetPanel : styles?.leadSendTemplateTabPanel}>
      <Box sx={styles?.leadSendTemplateErrorDownloadRow}>
        <Button
          variant="outline"
          icon={<DownloadOutlinedIcon />}
          onClick={onDownloadPrefilled}
          sx={{ width: { xs: '100%', sm: 'auto' } }}
        >
          {prefilledDownloadLabel ?? copy.sheet.downloadPrefilled}
        </Button>
        <Button variant="ghost" onClick={onDownloadBlank} sx={{ width: { xs: '100%', sm: 'auto' } }}>
          {copy.sheet.downloadBlank}
        </Button>
      </Box>

      <Box
        role="button"
        tabIndex={0}
        aria-label={copy.sheet.uploadHint}
        sx={{
          ...styles?.leadSendTemplateUploadZone,
          ...(embedded ? { minHeight: 96 } : null),
        }}
        onClick={handleZoneClick}
        onKeyDown={(event) => {
          if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            handleZoneClick();
          }
        }}
      >
        <CloudUploadOutlinedIcon sx={{ color: semantic.text.secondary, fontSize: 32 }} />
        <Typography sx={{ fontSize: typography.fontSizeSm, color: semantic.text.primary }}>
          {sheetFile?.name ?? copy.sheet.uploadHint}
        </Typography>
        {sheetFile ? (
          <Button
            variant="ghost"
            size="sm"
            onClick={(event) => {
              event.stopPropagation();
              onFileSelect?.(null);
            }}
          >
            {copy.sheet.replaceFile}
          </Button>
        ) : null}
      </Box>

      <input
        ref={fileInputRef}
        type="file"
        accept=".xlsx,.xls"
        hidden
        onChange={handleFileChange}
      />

      {fileErrors.length ? (
        <Alert severity="error">{fileErrors.join(' ')}</Alert>
      ) : null}

      {columnErrors.length ? (
        <Alert severity="error">{columnErrors.join(' ')}</Alert>
      ) : null}

      {hasRowErrors ? (
        <>
          <Alert severity="error">{copy.sheet.validationFailed(invalidCount)}</Alert>
          <Box sx={styles?.leadSendTemplateErrorPanel}>
            {(sheetValidation?.inlineMessages ?? []).slice(0, 5).map((message) => (
              <Typography
                key={message}
                sx={{ fontSize: typography.fontSizeSm, color: semantic.text.secondary }}
              >
                {message}
              </Typography>
            ))}
          </Box>
          <Button
            variant="outline"
            icon={<DownloadOutlinedIcon />}
            onClick={onDownloadErrorSheet}
            sx={{ width: { xs: '100%', sm: 'auto' } }}
          >
            {copy.sheet.downloadErrorSheet}
          </Button>
        </>
      ) : null}

      {isUploading ? (
        <Box aria-live="polite">
          <Typography sx={{ fontSize: typography.fontSizeSm, color: semantic.text.secondary, mb: 0.5 }}>
            {copy.sheet.uploadProgress(uploadProgress)}
          </Typography>
          <LinearProgress variant="determinate" value={uploadProgress} />
        </Box>
      ) : null}
    </Box>
  );
}
