import React, { useMemo } from 'react';
import { Box, Popover, Typography } from '@mui/material';
import ArticleOutlinedIcon from '@mui/icons-material/ArticleOutlined';
import { LEAD_CHAT_COPY } from '../constants/leadChatCopy';
import {
  LEAD_ATTACH_ITEM_THEMES,
  LEAD_MEDIA_ATTACH_ITEMS,
} from '../constants/leadChatAttachMenuConfig';
import useLeadChatSx from '../hooks/useLeadChatSx';
import LeadChatMediaAttachTooltip from './LeadChatMediaAttachTooltip';

function AttachMenuItem({ item, styles, onSelect }) {
  const Icon = item.icon;

  const content = (
    <Box
      component="button"
      type="button"
      role="menuitem"
      disabled={item.disabled}
      aria-disabled={item.disabled}
      sx={[
        styles.attachMenu?.item,
        item.disabled ? styles.attachMenu?.itemDisabled : null,
      ]}
      onClick={() => onSelect(item)}
    >
      <Box
        sx={{
          ...styles.attachMenu?.iconCircle,
          bgcolor: item.bg,
          color: item.color,
        }}
      >
        <Icon sx={{ fontSize: 20 }} />
      </Box>
      <Box sx={styles.attachMenu?.itemCopy}>
        <Typography sx={styles.attachMenu?.itemLabel}>{item.label}</Typography>
        {item.hint ? (
          <Typography sx={styles.attachMenu?.itemHint}>{item.hint}</Typography>
        ) : null}
      </Box>
    </Box>
  );

  if (!item.disabled || !item.disabledTooltipTitle) {
    return content;
  }

  return (
    <LeadChatMediaAttachTooltip
      title={item.disabledTooltipTitle}
      hint={item.hint}
      placement="right"
    >
      <Box component="span" sx={styles.attachMenu?.itemTooltipWrap}>
        {content}
      </Box>
    </LeadChatMediaAttachTooltip>
  );
}

export default function LeadChatComposerAttachMenu({
  anchorEl,
  open,
  onClose,
  canSendTemplate = false,
  canAttachMedia = true,
  onPickTemplate,
  onPickImage,
  onPickVideo,
  onPickDocument,
}) {
  const styles = useLeadChatSx();

  const mediaHandlers = {
    image: onPickImage,
    video: onPickVideo,
    document: onPickDocument,
  };

  const menuItems = useMemo(() => {
    const items = [];

    if (canSendTemplate) {
      items.push({
        id: 'template',
        label: LEAD_CHAT_COPY.composer.template,
        hint: LEAD_CHAT_COPY.composer.templateHint,
        icon: ArticleOutlinedIcon,
        disabled: false,
        onClick: onPickTemplate,
        ...LEAD_ATTACH_ITEM_THEMES.template,
      });
    }

    LEAD_MEDIA_ATTACH_ITEMS.forEach((mediaItem) => {
      const disabled = !canAttachMedia;
      items.push({
        ...mediaItem,
        disabled,
        disabledTooltipTitle: disabled
          ? LEAD_CHAT_COPY.composer.mediaLockedTitle(mediaItem.mediaNoun)
          : null,
        onClick: mediaHandlers[mediaItem.id],
      });
    });

    return items;
  }, [
    canAttachMedia,
    canSendTemplate,
    onPickDocument,
    onPickImage,
    onPickTemplate,
    onPickVideo,
  ]);

  const handleSelect = (item) => {
    if (item.disabled) return;
    onClose?.();
    item.onClick?.();
  };

  return (
    <Popover
      open={open}
      anchorEl={anchorEl}
      onClose={onClose}
      anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
      transformOrigin={{ vertical: 'bottom', horizontal: 'left' }}
      slotProps={{
        paper: { sx: styles.attachMenu?.paper, elevation: 8 },
      }}
    >
      <Box sx={styles.attachMenu?.list} role="menu" aria-label={LEAD_CHAT_COPY.composer.attach}>
        {menuItems.map((item) => (
          <AttachMenuItem
            key={item.id}
            item={item}
            styles={styles}
            onSelect={handleSelect}
          />
        ))}
      </Box>
    </Popover>
  );
}
