import { collectPayloadKeys, normalizeApiList } from '../utils/statusLogUtils';

export function extractStatusLogList(response) {
  return normalizeApiList(response);
}

export function buildStatusLogRows(rawList = []) {
  return rawList.map((row, index) => ({
    ...row,
    _rowKey: row._id || row.id || `${index}-${row.updated_at || row.created_at || 'status'}`,
  }));
}

export { collectPayloadKeys };
