const NEAR_DUPLICATE_WINDOW_MS = 60 * 1000;

function normalize(value) {
  if (value == null) return '';
  return String(value).trim();
}

export function getMessageText(message) {
  if (!message) return '';
  return normalize(
    message?.content?.body?.text
    || message?.content?.text
    || message?.text
    || message?.message
    || ''
  );
}

export function getMessageIdentityKeys(message) {
  if (!message) return [];
  return [message.id, message.msg_id, message.w_id, message.message_id]
    .filter((value) => value != null && value !== '')
    .map(String);
}

function getMessageTimestampMs(message) {
  const raw = message?.created_at || message?.timestamp || message?.updated_at;
  if (raw == null) return null;
  if (typeof raw === 'number') return raw < 10000000000 ? raw * 1000 : raw;
  const parsed = Date.parse(raw);
  return Number.isFinite(parsed) ? parsed : null;
}

function getContentType(message) {
  return normalize(message?.content?.type || message?.type || '').toUpperCase();
}

function normalizeContentType(type) {
  const value = normalize(type).toUpperCase();
  if (value === 'FILE' || value === 'DOCUMENT') return 'DOCUMENT';
  if (value === 'IMAGE' || value === 'PHOTO') return 'IMAGE';
  if (value === 'VIDEO') return 'VIDEO';
  if (value === 'AUDIO' || value === 'VOICE') return 'AUDIO';
  return value;
}

function isMediaType(type) {
  return type === 'IMAGE' || type === 'VIDEO' || type === 'AUDIO' || type === 'DOCUMENT';
}

export function isDuplicateLeadChatMessage(existing, incoming) {
  if (!existing || !incoming) return false;

  const aKeys = new Set(getMessageIdentityKeys(existing));
  const bKeys = getMessageIdentityKeys(incoming);
  if (bKeys.some((key) => aKeys.has(key))) return true;

  const existingRealIds = [...aKeys].filter((id) => !id.toLowerCase().startsWith('local-'));
  const incomingRealIds = bKeys.filter((id) => !id.toLowerCase().startsWith('local-'));
  if (existingRealIds.length > 0 && incomingRealIds.length > 0) return false;

  const textA = getMessageText(existing);
  const textB = getMessageText(incoming);
  if (textA && textB && textA === textB) {
    const tsA = getMessageTimestampMs(existing);
    const tsB = getMessageTimestampMs(incoming);
    if (tsA == null || tsB == null) return true;
    return Math.abs(tsA - tsB) <= NEAR_DUPLICATE_WINDOW_MS;
  }

  return false;
}

function isOptimisticMessage(message) {
  return getMessageIdentityKeys(message).some((id) => id.toLowerCase().startsWith('local-'));
}

function inferContentType(message) {
  const explicit = normalizeContentType(getContentType(message));
  if (isMediaType(explicit) || explicit === 'TEXT' || explicit === 'TEMPLATE') {
    return explicit;
  }

  const mime = normalize(message?.content?.mime_type || message?.mime_type).toLowerCase();
  if (mime.startsWith('image/')) return 'IMAGE';
  if (mime.startsWith('video/')) return 'VIDEO';
  if (mime.startsWith('audio/')) return 'AUDIO';
  if (mime.includes('pdf') || mime.includes('document') || mime.includes('msword')) {
    return 'DOCUMENT';
  }

  if (message?.content?.image || message?.image) return 'IMAGE';
  if (message?.content?.video || message?.video) return 'VIDEO';
  if (message?.content?.audio || message?.audio) return 'AUDIO';
  if (message?.content?.document || message?.document) return 'DOCUMENT';

  const url = normalize(
    message?.content?.media?.s3_object?.url
    || message?.content?.url
    || message?.url
    || ''
  ).toLowerCase();
  if (/\.(jpe?g|png|gif|webp)(\?|$)/.test(url)) return 'IMAGE';
  if (/\.(mp4|3gp|mov|webm)(\?|$)/.test(url)) return 'VIDEO';

  return explicit;
}

function unwrapIncomingMessage(message) {
  if (!message || typeof message !== 'object') return message;
  if (message.content || message.phone_number || message.msg_id || message.w_id) {
    return message;
  }
  return message.message || message.data || message;
}

export function findOptimisticOutboundIndex(messages, incomingRaw) {
  const incoming = unwrapIncomingMessage(incomingRaw);
  if (!incoming) return -1;

  const incomingType = inferContentType(incoming);
  const incomingOrigin = normalize(incoming?.origin).toUpperCase();
  if (incomingOrigin === 'INBOUND') return -1;

  const incomingText = getMessageText(incoming);
  let matchIndex = -1;

  (messages || []).some((message, index) => {
    if (!isOptimisticMessage(message)) return false;
    if (normalize(message?.origin).toUpperCase() !== 'OUTBOUND') return false;

    const messageType = inferContentType(message);
    if (incomingType && messageType && incomingType !== messageType) return false;

    if (isMediaType(incomingType || messageType)) {
      matchIndex = index;
      return true;
    }

    const messageText = getMessageText(message);
    if (incomingText && messageText && incomingText === messageText) {
      matchIndex = index;
      return true;
    }

    return false;
  });

  return matchIndex;
}

export function mergeIncomingWithOptimistic(existing, incoming) {
  const msgId = incoming?.msg_id || incoming?.w_id || incoming?.id || incoming?.message_id;
  const existingPreview = existing?.content?.previewUrl || existing?.content?.url;
  const incomingUrl =
    incoming?.content?.media?.s3_object?.url
    || incoming?.content?.media?.url
    || incoming?.content?.url
    || incoming?.content?.previewUrl;

  return {
    ...existing,
    ...incoming,
    msg_id: msgId || existing?.msg_id,
    w_id: incoming?.w_id || incoming?.msg_id || existing?.w_id,
    content: {
      ...(existing?.content || {}),
      ...(incoming?.content || {}),
      url: incomingUrl || existingPreview,
      previewUrl: incomingUrl || existingPreview,
    },
  };
}
