export function formatAttachmentFileSize(bytes) {
  if (!bytes || bytes <= 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB'];
  let size = bytes;
  let unitIndex = 0;
  while (size >= 1024 && unitIndex < units.length - 1) {
    size /= 1024;
    unitIndex += 1;
  }
  const precision = unitIndex === 0 ? 0 : size >= 10 ? 0 : 1;
  return `${size.toFixed(precision)} ${units[unitIndex]}`;
}

function getUploadMessageType(file) {
  if (!file?.type) return 'file';

  const mime = file.type.toLowerCase();

  if (mime.startsWith('image/')) return 'image';
  if (mime.startsWith('video/')) return 'video';
  if (mime.startsWith('audio/')) return 'audio';
  if (
    mime.includes('pdf')
    || mime.includes('document')
    || mime.includes('msword')
    || mime.includes('spreadsheet')
    || mime.includes('text/plain')
  ) {
    return 'file';
  }

  return 'file';
}

export function buildSendMessageFormData({ phoneNumber, draftMessage, file }) {
  const formData = new FormData();
  formData.append('phone_number', phoneNumber);

  if (file) {
    const uploadType = getUploadMessageType(file);
    formData.append('file', file);
    formData.append('type', uploadType);

    const caption = (draftMessage || '').trim();
    if (caption && uploadType !== 'audio') {
      formData.append('text', caption);
    }
  } else {
    formData.append('type', 'text');
    formData.append('text', draftMessage || '');
  }

  return formData;
}

export function buildOptimisticMessage({ phoneNumber, botNumber, draftMessage, file }) {
  const localId = `local-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const type = file
    ? (file.type.startsWith('image/')
      ? 'image'
      : file.type.startsWith('video/')
        ? 'video'
        : file.type.startsWith('audio/')
          ? 'audio'
          : 'document')
    : 'text';
  const previewUrl = file ? URL.createObjectURL(file) : '';

  return {
    id: localId,
    msg_id: localId,
    w_id: localId,
    phone_number: phoneNumber,
    bot_number: botNumber,
    origin: 'OUTBOUND',
    created_at: new Date().toISOString(),
    content: {
      type,
      text: draftMessage || '',
      body: { text: draftMessage || '' },
      filename: file?.name || '',
      url: previewUrl,
      previewUrl,
    },
    status: { type: 'sent' },
  };
}
