/** Columns shown only via row actions — not as table cells. */
export const HIDDEN_RECORD_TABLE_COLUMN_KEYS = new Set(['audio_summary']);

const CREATED_AT_KEY = 'created_at';

/**
 * Prepares record table columns for display: hides action-only columns and
 * moves created_at to the last data column (before the actions column).
 */
export function orderRecordTableColumns(columns = []) {
  const displayColumns = columns.filter(
    (column) => column?.key && !HIDDEN_RECORD_TABLE_COLUMN_KEYS.has(column.key)
  );

  const createdAtColumn = displayColumns.find((column) => column.key === CREATED_AT_KEY);
  const otherColumns = displayColumns.filter((column) => column.key !== CREATED_AT_KEY);

  if (!createdAtColumn) {
    return otherColumns;
  }

  return [...otherColumns, createdAtColumn];
}
